create table public.studio_media (id uuid primary key default gen_random_uuid(), object_path text not null unique check(object_path ~ '^[0-9a-f-]{36}\.(jpg|png|webp|mp4)$'), mime_type text not null check(mime_type in ('image/jpeg','image/png','image/webp','video/mp4')), bucket_id text not null default 'bds-media' check(bucket_id='bds-media'), title text not null check(char_length(title) between 1 and 160), slot text not null check(slot in ('hero','photo','audio','content','wedding','film','brand','academy')), published boolean not null default false, created_at timestamptz not null default now()); alter table public.studio_media enable row level security; revoke all on public.studio_media from public,anon,authenticated; grant select on public.studio_media to anon,authenticated; grant insert,update,delete on public.studio_media to authenticated; create policy media_public_read on public.studio_media for select to anon,authenticated using(published); create policy media_admin_all on public.studio_media for all to authenticated using(exists (select 1 from public.studio_admin_memberships m where m.user_id=(select auth.uid()))) with check(exists (select 1 from public.studio_admin_memberships m where m.user_id=(select auth.uid()))); create unique index studio_media_published_slot on public.studio_media(slot) where published; insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('bds-media','bds-media',false,20971520,array['image/jpeg','image/png','image/webp','video/mp4']); create policy bds_media_admin_insert on storage.objects for insert to authenticated with check(bucket_id='bds-media' and exists (select 1 from public.studio_admin_memberships m where m.user_id=(select auth.uid()))); create policy bds_media_admin_read on storage.objects for select to authenticated using(bucket_id='bds-media' and exists (select 1 from public.studio_admin_memberships m where m.user_id=(select auth.uid()))); create policy bds_media_published_read on storage.objects for select to anon,authenticated using(bucket_id='bds-media' and exists(select 1 from public.studio_media m where m.object_path=storage.objects.name and m.published));
